/// Enumeration for crypto algorithm parameters.
///
/// **Since Tizen:**
/// - 3.0
///
/// **See also:**
/// - `ckmc_algo_type_e`
/// - `ckmc_key_s`
/// - `ckmc_kdf_prf_e`
/// - `ckmc_kbkdf_mode_e`
/// - `ckmc_kbkdf_counter_location_e`
/// - `ckmc_kem_type_e`
/// - `__ckmc_hash_algo`
/// @nodoc
abstract class ckmc_param_name {
  /// < Integer - type of algorithm
  static const int CKMC_PARAM_ALGO_TYPE = 1;

  /// < Buffer - initialization vector
  static const int CKMC_PARAM_ED_IV = 101;

  /// < Integer - ctr length in bits
  static const int CKMC_PARAM_ED_CTR_LEN = 102;

  /// < Buffer - Additional Authentication Data for AES GCM
  static const int CKMC_PARAM_ED_AAD = 103;

  /// < Integer - tag length in bits
  static const int CKMC_PARAM_ED_TAG_LEN = 104;

  /// < Buffer - RSA OAEP label (not supported at the moment)
  static const int CKMC_PARAM_ED_LABEL = 105;

  /// < Integer - function to be used both as Label and MGF hash function
  /// in OAEP padding. If not given, the default #CKMC_HASH_SHA1 is used (Since 6.0)
  static const int CKMC_PARAM_ED_OAEP_HASH = 106;

  /// < Integer - type of padding algorithm (Since 10.0)
  static const int CKMC_PARAM_ED_PADDING = 107;

  /// < Integer - pseudo-random function number (Since 6.0)
  static const int CKMC_PARAM_KDF_PRF = 401;

  /// < Integer - length of the derived key in bytes. The value must be one of
  /// {16, 24, 32} (Since 6.0)
  static const int CKMC_PARAM_KDF_LEN = 402;

  /// < Integer - KDF mode number (Since 6.0)
  static const int CKMC_PARAM_KBKDF_MODE = 403;

  /// < Buffer - the purpose for the derived key. Conflicts with
  /// #CKMC_PARAM_KBKDF_FIXED_INPUT (Since 6.0)
  static const int CKMC_PARAM_KBKDF_LABEL = 404;

  /// < Buffer - information related to the derived key. Conflicts with
  /// #CKMC_PARAM_KBKDF_FIXED_INPUT (Since 6.0)
  static const int CKMC_PARAM_KBKDF_CONTEXT = 405;

  /// < Buffer - KBKDF fixed input replacing context and label
  /// (Since 6.0). Conflicts with:
  /// - #CKMC_PARAM_KBKDF_LABEL,
  /// - #CKMC_PARAM_KBKDF_CONTEXT,
  /// - #CKMC_PARAM_KBKDF_LLEN,
  /// - #CKMC_PARAM_KBKDF_NO_SEPARATOR
  static const int CKMC_PARAM_KBKDF_FIXED_INPUT = 406;

  /// < Integer - specifies location of the counter in KBKDF (Since 6.0)
  static const int CKMC_PARAM_KBKDF_COUNTER_LOCATION = 407;

  /// < Integer - specifies the length of the counter representation in bits
  /// in KBKDF. The value must be one of {8, 16, 24, 32}. If not set, the
  /// default value = 32 will be used. (Since 6.0)
  static const int CKMC_PARAM_KBKDF_RLEN = 408;

  /// < Integer - specifies the extent of the length suffix representation
  /// in bits in KBKDF. The value must be one of {0, 8, 16, 24, 32}. If set to
  /// 0 the length suffix will be skipped. If not set, the default value = 32
  /// will be used. The length suffix is skipped if
  /// #CKMC_PARAM_KBKDF_FIXED_INPUT is passed and this parameter conflicts
  /// with it. (Since 6.0)
  static const int CKMC_PARAM_KBKDF_LLEN = 409;

  /// < Integer - presence of this parameter will skip the zero
  /// octet separator between label and context in KBKDF.
  /// All values are allowed. This parameter conflicts with
  /// #CKMC_PARAM_KBKDF_FIXED_INPUT. (Since 6.0)
  static const int CKMC_PARAM_KBKDF_NO_SEPARATOR = 410;

  /// < Buffer - EC public key in DER form (Since 6.0)
  static const int CKMC_PARAM_ECDH_PUBKEY = 411;

  /// < Integer - specifies the KEM type (Since 7.0)
  static const int CKMC_PARAM_KEM_TYPE = 412;
}

